use vstd::prelude::*;

verus! {
    fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
        requires
            x.len() > 0, // The input array must be non-empty
        ensures
            result.len() == x.len() // The output array has the same length as the input
            && (forall |i: nat| (i < result.len() as nat) ==> 
                (if i == 0 || i == (result.len() as nat) - 1 {
                    result[i] == 0.5 // The weight at the first and last index is 0.5
                } else {
                    result[i] == 1.0 // The weight at all other indices is 1.0
                }))
    {
        let mut result: Vec<f32> = vec![0.0; x.len()]; // Initialize result with the same length as x

        let len = x.len() as nat; // Get the length of the input vector

        // Iterate over the indices of the result vector
        for i in 0..len {
            if i == 0 || i == len - 1 {
                result[i as usize] = 0.5; // Set weight for first and last index
            } else {
                result[i as usize] = 1.0; // Set weight for all other indices
            }
        }

        result // Return the result vector
    }
}

